class Complex {
    double re, im;
public:
    Complex(double r = 0, double i = 0) : re(r), im(i) {}
    // member form: left operand is *this, right operand is the parameter
    Complex operator+(const Complex& o) const {
        return Complex(re + o.re, im + o.im);
    }
};
// c1 + c2 is translated by the compiler to c1.operator+(c2)

class Counter {
    int n;
public:
    Counter(int v = 0) : n(v) {}
    Counter operator-() const { return Counter(-n); }   // unary minus: -c
    Counter& operator++() { ++n; return *this; }        // prefix  ++c
    Counter operator++(int) {                           // postfix c++ (dummy int)
        Counter old = *this;  ++n;  return old;         // returns the OLD value
    }
    int get() const { return n; }
};

class Complex {
    double re, im;
public:
    Complex(double r = 0, double i = 0) : re(r), im(i) {}
    Complex operator-(const Complex& o) const { return Complex(re - o.re, im - o.im); }
    bool operator==(const Complex& o) const { return re == o.re && im == o.im; }
    friend Complex operator*(const Complex& a, const Complex& b);   // friend: 2 params
    friend ostream& operator<<(ostream& out, const Complex& c);     // stream is left operand
};
Complex operator*(const Complex& a, const Complex& b) {
    return Complex(a.re*b.re - a.im*b.im, a.re*b.im + a.im*b.re);
}
ostream& operator<<(ostream& out, const Complex& c) {
    return out << c.re << " + " << c.im << "i";   // returns the stream for chaining
}

class Buffer {
    int* data; int size;
public:
    Buffer(int n) : data(new int[n]), size(n) {}
    ~Buffer() { delete[] data; }
    Buffer& operator=(const Buffer& o) {          // copy assignment: deep copy
        if (this != &o) {                         // guard against b = b
            delete[] data;  size = o.size;  data = new int[size];
            for (int i = 0; i < size; i++) data[i] = o.data[i];
        }
        return *this;                             // allows a = b = c
    }
    int& operator[](int i) { return data[i]; }    // subscript: reference so b[2] = 7 works
    int operator()(int i, int j) const { return data[i] + data[j]; }  // call: b(1, 2)
};

#include <iostream>
using namespace std;
struct Ctr {
    int n;
    Ctr(int v) : n(v) {}
    Ctr& operator++()    { ++n; return *this; }                 // prefix
    Ctr  operator++(int) { Ctr old = *this; ++n; return old; }  // postfix
};
int main() {
    Ctr a(5);
    Ctr b = a++;       // a.operator++(0): b receives the OLD value
    Ctr c = ++a;       // a.operator++():  c receives the NEW value
    cout << a.n << " " << b.n << " " << c.n;
}

#include <iostream>
using namespace std;
class M {
    int v;
public:
    M(int x = 0) : v(x) {}
    friend M operator+(const M &a, const M &b) { return M(a.v + b.v); }
    M& operator+=(const M &o) { v += o.v; return *this; }
    friend ostream& operator<<(ostream &os, const M &m) { return os << "[" << m.v << "]"; }
};
int main() {
    M a(2), b(3), c = 10 + a;   // 10 -> M(10), then operator+(M(10), a)
    (a += b) += c;         // a += b returns a itself, so += c also changes a
    cout << a << c << b;
}

