class Distance {
    int feet; float inches;
public:
    Distance() : feet(0), inches(0) {}
    Distance(float metres) {                 // basic -> class: one-argument constructor
        float f = metres * 3.280833f;        // metres to decimal feet
        feet = int(f);  inches = 12 * (f - feet);
    }
    void show() const { cout << feet << "' " << inches << "\""; }
};
Distance d1 = 2.0f;        // constructor converts 2.0 metres -> 6' 6.74"
Distance d2;  d2 = 1.0f;   // temporary Distance(1.0f) is built, then assigned

class Distance {
    int feet; float inches;
public:
    Distance(int f, float i) : feet(f), inches(i) {}
    operator float() const {                 // class -> basic: conversion function
        float decimalFeet = feet + inches / 12;
        return decimalFeet / 3.280833f;      // result in metres
    }
};
Distance d(6, 6.74f);
float metres = d;                 // implicit: operator float() is called -> 2.0
cout << static_cast<float>(d);    // explicit form, same function runs

class Celsius {
    double deg;
public:
    Celsius(double d = 0) : deg(d) {}
    double get() const { return deg; }
};
class Fahrenheit {
    double deg;
public:
    Fahrenheit(double d = 0) : deg(d) {}
    Fahrenheit(const Celsius& c) : deg(c.get() * 9 / 5 + 32) {}  // conversion in destination
    double get() const { return deg; }
};
Celsius c(100);
Fahrenheit f = c;      // Fahrenheit(const Celsius&) runs -> f.get() is 212

