concepts.text:
class Shape {                     // base class
protected:
    double x, y;                  // usable in derived classes, hidden from outside
public:
    Shape(double a, double b) : x(a), y(b) {}
    virtual double area() const { return 0; }
    virtual ~Shape() {}           // virtual destructor: safe delete through Shape*
};
class Circle : public Shape {     // derived class, public inheritance
    double r;
public:
    Circle(double a, double b, double r0) : Shape(a, b), r(r0) {}  // base ctor first
    double area() const override { return 3.14159 * r * r; }      // redefinition
};

class A { public: int x; };
class B : public A { };                 // single
class C : public A { };                 // hierarchical: A -> B and A -> C
class D : public B, public C { };       // multiple, and multipath (diamond) through A
class E : public B { };                 // multilevel: A -> B -> E
int main() {
    D d;
    // d.x = 1;      // ERROR: ambiguous - D holds two copies of A (via B and via C)
    d.B::x = 1;      // OK: choose a path with the scope resolution operator
    d.C::x = 2;      // the other copy
}

class A { public: A() { cout << "A ctor "; }  ~A() { cout << "~A "; } };
class B : public A { public: B() { cout << "B ctor "; }  ~B() { cout << "~B "; } };
class C : public B { public: C() { cout << "C ctor "; }  ~C() { cout << "~C "; } };
int main() {
    C obj;              // multilevel: constructors run top-down
}                       // destructors run bottom-up when obj goes out of scope
// Output: A ctor B ctor C ctor ~C ~B ~A

class Person {
    string name;
public:
    Person(const string& n) : name(n) { cout << "Person(" << name << ") "; }
};
class Student : public Person {
    int roll;
public:
    // Person has no default constructor, so its argument must be passed here
    Student(const string& n, int r) : Person(n), roll(r) { cout << "Student(" << r << ") "; }
};
Student s("Asha", 7);   // prints: Person(Asha) Student(7)

